-- ============================================================
-- 10_group_value_distribution.sql (propfit)
-- 목적: 07의 6개 그룹 각각의 "값 분포"를 낸다 — 예: 성별 그룹 안에서
--       "여성(High)"=30%, "여성(Low)"=10%, ... 처럼 그룹 내부 세그먼트 하나하나가
--       전체 device 대비 몇 %인지.
--
-- 방식(자원 소모 회피, 2026-07-24): 07 1차 버전이 device_ifa별로 UNNEST(billions of rows)
--       + 9개 컬럼 ARRAY_AGG를 한 번에 GROUP BY 하다가 자원 고갈로 실패했던 것과 달리,
--       이번엔 집계 기준(GROUP BY)이 device_ifa가 아니라 (그룹, segment_id) — 최대 985종
--       조합이라 결과 집합 자체가 작다. 그래서 순서를 바꿨다:
--       1) UNNEST로 device_ifa×segment_id를 풀되, 우리가 보려는 985개 ID 외의 나머지는
--          바로 걸러낸다(contains(...)로 사전 필터 — 관계없는 세그먼트를 다 들고 있지 않음).
--       2) (그룹, segment_id) 단위로 GROUP BY해서 COUNT(DISTINCT device_ifa) — 결과는
--          최대 985행이라 가볍다.
--       3) 이렇게 작아진 결과에만 segment_category를 JOIN해서 이름을 붙인다(985행 JOIN은
--          부담 없음 — 53M행에 JOIN했다가 문제됐던 것과 다름).
-- 참고: 6개 그룹 ID가 서로 겹치지 않음을 확인했다(4+7+241+420+184+129=985, 전체 합집합도
--       985개로 정확히 일치) — 그래서 CASE WHEN으로 그룹 태깅해도 한 segment_id가 두
--       그룹에 동시에 잡힐 위험은 없다.
-- 비율 분모: skp에 세그먼트가 하나라도 있는 device_ifa 전체(~53.3M, 07/08/09와 동일) —
--       그룹 자체의 보유자 수가 아니라 전체 모집단 기준이라, 같은 그룹 안의 값들끼리도
--       합이 그 그룹의 reach(07번 결과)를 넘을 수 있다(avg_matched>1인 값 많음, 즉 한
--       device가 같은 그룹에서 여러 값을 동시에 가짐 — 예: 성별 avg 1.95).
-- COUNT(DISTINCT device_ifa) 대신 COUNT(*)를 써도 거의 같은 값이 나올 것이다(한 device의
--       segments 문자열 안에 같은 ID가 중복 등장하는 경우가 없다고 가정) — 이 쿼리도 느리면
--       COUNT(*)로 바꿔서 가볍게 할 수 있다.
-- ============================================================

WITH segments_latest AS (
    SELECT
        ad_id AS device_ifa,
        CAST(segments AS VARCHAR) AS segments,
        ROW_NUMBER() OVER (
            PARTITION BY ad_id
            ORDER BY year DESC, month DESC, day DESC
        ) AS rn
    FROM "propfit"."skp"
    WHERE NOT (year = '2024' AND month = '12' AND day = '31')   -- 깨진 .tmp 파티션만 제외
      AND CAST(id_type AS VARCHAR) = '2'
      AND ad_id IS NOT NULL AND trim(CAST(ad_id AS VARCHAR)) <> ''
),
seg1 AS (
    SELECT device_ifa, split(segments, ';') AS segment_ids
    FROM segments_latest
    WHERE rn = 1
),
seg_long AS (
    -- 관심 대상 985개 ID로 사전 필터한 뒤 풀어서(long format) 그룹 태깅
