            WHEN contains(split('10010,10011,10012,10013,10014,10021,10022,10023,10024,10025,10026,10027,10028,10029,10030,10031,10032,10033,10034,20484,49688,49689,49690,10047,10048,10049,10050,10051,10052,10053,10054,10055,10056,13451,49717,49718,49719,49720,49721,49722,10057,10058,10059,10060,10061,10062,10063,10386,10387,10439,10440,10441,10442,27985,49723,49726,10220,10221,10222,10223,10224,10225,10226,10227,10228,10229,10230,10231,49675,49676,49677,49678,49679,49680,49681,49682,49683,49684,49685,10249,10250,10251,10252,10253,10254,10255,10256,10257,10258,10259,49691,49692,49693,49694,49695,49696,49697,49698,10260,10261,10262,10263,10264,10265,10266,10267,10268,10269,10270,10337,10338,10339,10340,10348,10349,10350,49708,49709,49712,49713,49714,49715,10280,10281,10282,10283,10284,10443,10277,10286,10287,10288,10289,10290,10291,10293,10294,10295,10297,10298,10299,10300,10301,10321,10322,10323,10324,10325,10326,10327,10328,10329,10330,10331,10332,10333,10336,49733,49734,10351,10352,10353,10354,10355,10356,10357,10370,10375,10376,49700,49701,49702,49703,49705,49706,49707,50008,10035,10036,10037,10038,10039,10040,10041,10042,10043,10044,10045,10046,10271,10272,10273,10274,10275,10276,10278,10279,10285,10335,49727,49728,49729,49730,49732,11212,11213,11214,11215,11216,11217,11218,11219,11220,20630,49758,49759,49760,50180,11227,11228,11229,11230,11231,11232,11233,11234,11236,49792,49793,49794,49795,49796,49797,50138,50144,11237,11238,11239,11300,49799,49800,49801,49802,49804,49805,49806,49807,49808,50143,50166,50765,11241,11242,11243,11244,11245,11246,11247,11248,11249,11250,11251,11252,11253,49746,49747,49748,49749,49750,49751,49752,49753,49754,49755,11254,11255,11256,11257,11258,11259,11260,11262,11263,11264,11265,49761,49762,49763,49764,49765,49766,49767,49768,11267,11268,11269,11270,11271,11272,11273,11274,11294,11299,49783,49784,49786,49787,49788,49789,49790,50134,50137,50141,50146,50148,50155,50156,11221,11222,11223,11224,11225,11226,11275,11276,11277,11278,11280