            WHEN contains(split('26280,26281,26282,26284,26285,26286,26287,26288,26289,26290,26291,26292,26293,26294,26295,26299,26306,26308,26309,26310,26311,26312,26313,26314,26425,26766,26322,26323,26324,26325,26326,26342,26343,26344,26345,26346,26347,26348,26349,26350,26351,26352,26353,26354,30367,30368,26355,26356,26357,26358,26359,26360,26361,26362,26363,26365,26366,26367,26368,26369,26370,26372,26373,26374,26375,26380,26381,26382,26383,26384,26385,26386,26388,26389,26390,26392,26393,26394,26395,26396,26397,26398,26399,26400,26401,26403,26404,26405,26406,26407,26408,26410,26413,26416,26418,26419,26420,26421,26422,26423,26424,19661,26426,22335,22336,22337,22338,22339,22340,22341,22342,22343,22344,22345,22346,22347,22348,22349,22350,22351,22352,22353,22355,22356,22357,22358,22359,22360,22361,22362,22364,22365,22366,22367,22368,22369,22370,22371,22372,22373,22374,37687,37695,37703,37683,37694,37697,37700,37689,37691,37698,37699,37701,37702,37705,37690,37704,37685,37686,37696,49372,49373,49374,49375,49376,49379,49381,49382,49383,49384,49390,49391,49393,49394,49395,49396,49397,49399,49400,49402,49406,50343,50344,50346', ','), t.segment_id) THEN '콘텐츠 관심사'
            WHEN contains(split('26937,26941,26946,49386,49387,26948,26949,26950,26952,26957,27009,26610,27151,27209,27699,49404,49411,49450,49605,49606,49607,26625,26929,27011,27013,49405,49407,50215,27015,27016,50191,26924,26926,26932,26935,26986,27049,49398,49403,49742,50188,50189,50190,26978,27334,27335,49408,49410,50230,26604,26609,26611,26612,26615,26666,26667,27613,50236,26607,26755,26959,27063,50216,50217,50218,50219,50220,50222,50224,50225,50226,50227,50228,50229,26645,27348,26634,26740,49388,49389,49392,49737,49738,49739,49740,49741,26662,27155,31327,31329,31331,31349,31350,31632,31637,31638,33025,49599,49602,49603,26591,26629,26630,26631,26633,26646,26649,26663,26664,27341,27353,49370,49452,49453,49455,49456,49457,49458,49586,49587,49588,49589,49591,49594,49597,49598,50232,50233,50234', ','), t.segment_id) THEN '기타'
