),
counted AS (
    SELECT feature_group, segment_id, COUNT(DISTINCT device_ifa) AS device_cnt
    FROM seg_long
    GROUP BY feature_group, segment_id
),
total AS (
    SELECT count(*) AS total_devices FROM seg1
)
SELECT
    c.feature_group,
    c.segment_id,
    sc.segment_name,
    c.device_cnt,
    round(100.0 * c.device_cnt / t.total_devices, 2) AS pct_of_total_devices
FROM counted c
CROSS JOIN total t
LEFT JOIN "prod-ptbwa-dw"."segment_category" sc ON c.segment_id = sc.segment_id
ORDER BY c.feature_group, c.device_cnt DESC
;
